def q(question, answer, refs=(), kind='Проверенный факт'):
    return dict(question=question, answer=answer, source_ids=list(refs), kind=kind)

def c(id, topic, title, pitch, why, mechanic, prep, examples, expansion, caution='', recommend=False):
    categories.append(dict(id=f'{id:02}', topic=topic, title=title, pitch=pitch,
        why=why, mechanic=mechanic, preparation=prep, examples=examples,
        expansion=expansion, host_note=caution, recommended=recommend))

